import { defineCommand } from '../../lib/define-command.js';
import { defineOption } from '../../lib/define-option.js';
import { k8sUpdate } from '../../lib/k8s.js';
import { styleText } from '../../lib/style-text.js';
import { Logger } from '../../logger.js';
import { tags } from '../../parsers.js';
import { orgaIdOrNameOption } from '../global.options.js';
import { k8sIdOrNameArg } from './k8s.args.js';

export const k8sUpdateCommand = defineCommand({
  description: 'Update the settings of a Kubernetes cluster',
  since: null,
  options: {
    name: defineOption({
      name: 'name',
      schema: z.string().min(1).optional(),
      description: 'New cluster name',
      placeholder: 'name',
    }),
    description: defineOption({
      name: 'description',
      schema: z.string().max(4096).optional(),
      description: 'Free-form cluster description',
      placeholder: 'description',
    }),
    tag: defineOption({
      name: 'tag',
      schema: z.string().transform(tags).optional(),
      description: 'Semantic tags replacing the existing ones (comma-separated, e.g.: env:prod,team:platform)',
      placeholder: 'tag[,tag...]',
    }),
    autoscaling: defineOption({
      name: 'autoscaling',
      schema: z
        .enum(['true', 'false'])
        .transform((value) => value === 'true')
        .optional(),
      description: 'Enable or disable the cluster autoscaler',
      placeholder: 'true|false',
      complete: () => ['true', 'false'],
    }),
    org: orgaIdOrNameOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const { name, description, tag, autoscaling, org } = options;

    const updates = {};
    if (name != null) updates.name = name;
    if (description != null) updates.description = description;
    if (tag != null) updates.tags = tag;
    if (autoscaling != null) updates.features = { autoscalingEnabled: autoscaling };

    if (Object.keys(updates).length === 0) {
      throw new Error('Nothing to update, use at least one of --name, --description, --tag or --autoscaling');
    }

    try {
      const cluster = await k8sUpdate(org, clusterIdOrName, updates);
      const label = cluster?.name ?? clusterIdOrName.addon_name ?? clusterIdOrName.operator_id;
      Logger.printSuccess(`Cluster ${styleText('green', label)} successfully updated`);
    } catch (error) {
      throw new Error(`Failed to update Kubernetes cluster: ${error.message}`);
    }
  },
});
